:root:has(.chat-markdown[data-streaming],.live-tool-shine) [data-workspace-area="conversation"]::after{animation:sx-bloom 14s var(--sx-inout) infinite}
@keyframes sx-bloom{0%{opacity:0;transform:scale(.7)}45%{opacity:1}100%{opacity:0;transform:scale(1.15)}}
[data-slot="sidebar-inner"]::before{content:"";position:absolute;left:50%;bottom:58px;width:120px;height:84px;margin-left:-60px;pointer-events:none;background:var(--sx-mark) center/contain no-repeat;opacity:.07}
@media (prefers-reduced-motion:reduce){[data-workspace-area="conversation"]::before,[data-workspace-area="conversation"]::after,[data-slot="sidebar-inner"]::before{animation:none!important;transition:none!important}h1:has([data-draft-project-trigger])::before{content:none}[data-workspace-area="conversation"],[data-slot="sidebar-inner"]{--sx-actor:none;--sx-actor-2:none;--sx-pc:transparent}}
